 const dim=(x1,y1,x2,y2,t)=>`<path d="M${x1} ${y1}L${x2} ${y2}" stroke="#567887" marker-start="url(#arr)" marker-end="url(#arr)"/>${text((x1+x2)/2+((x1===x2)?26:0),(y1+y2)/2-5,t)}`;
