 for(const u of l.units){const sideways=u.run!=='south';svg+=`<g data-cabinet="${esc(u.id.slice(2))}" tabindex="0" role="button" aria-label="${esc(u.name)}">${rect(u.x,u.z,sideways?u.d:u.w,sideways?u.w:u.d,['range','dishwasher','fridge'].includes(u.unitType)?'#d5e2e8':'#ddd1bb')}${u.width>=10?text(X(u.x),Y(u.z)+4,u.id.slice(2),11):''}</g>`;}
