 svg+=dim(X(l.island.x-l.island.w/2),Y(l.island.z-l.island.d/2)-15,X(l.island.x+l.island.w/2),Y(l.island.z-l.island.d/2)-15,inches(k.islandWidth));
 svg+=dim(X(l.island.x+l.island.w/2)+35,Y(l.island.z-l.island.d/2),X(l.island.x+l.island.w/2)+35,Y(l.island.z+l.island.d/2),inches(k.islandLength));
 svg+=dim(X(D.west),Y(D.south)+30,X(D.east),Y(D.south)+30,inches((D.east-D.west)*12));
