 if(run==='west'){const start=(D.windowCenter-2-D.north)*12;s+=`<rect x="${ox+start*scale}" y="${yy(96)}" width="${48*scale}" height="${54*3}" fill="#d8edf4" stroke="#15272d"/><text x="${ox+(start+24)*scale}" y="${yy(70)}" font-size="12" text-anchor="middle">Source window</text>`;}
 for(const b of stoneLayout(k).splashes.filter(b=>b.run===run)){const start=b.start-(run==='south'?k.corner:0),a=Math.max(0,start),end=Math.min(length,start+b.width);if(end>a)s+=`<rect x="${ox+a*scale}" y="${yy(b.top)}" width="${(end-a)*scale}" height="${b.height*3}" fill="${stone.splashMaterial==='match'?'#e8dfcd':'#edece2'}" stroke="#b7b9aa"/>`;}
 for(const u of items){const x=ox+u.start*scale,w=u.width*scale,h=u.h*12,appliance=['range','fridge','dishwasher'].includes(u.unitType);s+=`<rect x="${x}" y="${yy(h)}" width="${w}" height="${h*3}" fill="${appliance?'#c1d0d5':'#b3a38c'}" stroke="#59666b"/>`;
 if(!appliance&&!['filler','panel'].includes(u.unitType))s+=`<rect x="${x+m.toeRecess*scale/8}" y="${yy(m.toeHeight)}" width="${w-m.toeRecess*scale/4}" height="${m.toeHeight*3}" fill="#4a4e4a"/>`;
 if(u.width>5)s+=`<text x="${x+w/2}" y="${baseline+17}" font-size="11" text-anchor="middle">${esc(u.id.slice(2))}</text><text x="${x+w/2}" y="${baseline+32}" font-size="11" text-anchor="middle">${inches(u.width)}</text>`;
 if(!['fridge','range'].includes(u.unitType)&&!u.tallFill)s+=`<rect x="${x}" y="${yy(l.top)}" width="${w}" height="${k.counterThickness*3}" fill="#e7e9e6" stroke="#68777e"/>`;
 if(u.unitType==='range')s+=`<rect x="${x}" y="${yy(stone.hoodBottom+9)}" width="${w}" height="27" fill="#899da3"/><text x="${x+w/2}" y="${yy(stone.hoodBottom+12)}" font-size="11" text-anchor="middle">Hood</text>`;
 }
 for(const c of spec.cabinets.filter(c=>c.run===run||c.run===run+' upper')){const u=items.find(u=>u.id.slice(2)===c.cabinet_id||u.id.slice(2)+'-BR'===c.cabinet_id);const upper=!u;const start=u?u.start+(c.cabinet_id.endsWith('-BR')?.75:0):run==='west'?(c.center_y_ft-D.north)*12-c.assembly_width_in/2:(c.center_x_ft-D.west)*12-c.assembly_width_in/2-k.corner;
 if(upper)s+=`<rect x="${ox+start*scale}" y="${yy(c.case_top_aff_in)}" width="${c.assembly_width_in*scale}" height="${c.case_height_in*3}" fill="#b3a38c" stroke="#59666b"/>`;
 for(const f of spec.fronts.filter(f=>f.cabinet===c.cabinet_id)){const x=ox+(start+c.assembly_width_in/2+f.x-f.width/2)*scale,y=yy(f.y+f.height/2),w=f.width*scale,h=f.height*3;s+=`<rect x="${x}" y="${y}" width="${w}" height="${h}" fill="${upper&&k.upperFront==='glass'?'#cbdad5':'#dfd1bb'}" stroke="#59666b" stroke-width=".5"/>`;if(k.front==='shaker'&&f.width>m.stileWidth*2&&f.height>m.stileWidth*2)s+=`<rect x="${x+m.stileWidth*scale}" y="${y+m.stileWidth*3}" width="${w-m.stileWidth*scale*2}" height="${h-m.stileWidth*6}" fill="none" stroke="#a29b8b" stroke-width=".5"/>`;if(f.pulls)s+=`<path d="M${x+w/2-m.pullCenters*scale/2} ${yy(f.pull_center_aff_in)}h${m.pullCenters*scale}" stroke="#454e4b" stroke-width="2"/>`;}
 if(upper)s+=`<text x="${ox+(start+c.assembly_width_in/2)*scale}" y="${yy(c.case_top_aff_in)-5}" text-anchor="middle" font-size="10">${esc(c.cabinet_id)}</text>`;
 }
 s+=`<text x="555" y="${yy(l.top)-5}" font-size="11">Top ${inches(l.top)}</text></g></svg>`;return s;
